30	type RuntimeServiceDefinition = ServiceDefinition<unknown, Queries<unknown>, Commands<unknown>>;
31	type RuntimeQueryDefinition = AnyQueryDefinition<unknown>;
32	
33	export { clearRegistry, describeService, getRegisteredServices, getService, listServices };
34	
35	/**
36	 * Registers a service on the dev server and returns its runtime surface.
37	 *
38	 * The server is a relay hub: when a channel is installed (the `services` preset does this on a real
39	 * websocket transport) it bridges every connected manager tab. Without a channel — static builds and
40	 * the index builder — the runtime stays local-only.
41	 */
42	export function registerService<
43	  TState,
44	  TQueries extends Queries<TState>,
45	  TCommands extends Commands<TState>,
46	>(
47	  definition: ServiceDefinition<TState, TQueries, TCommands>,
48	  registration?: ServiceRegistrationOptions<TState, TQueries, TCommands>
49	): ServiceInstance<TState, TQueries, TCommands> & ServiceRegistryApi {
50	  return registerServiceCore(definition, registration, { relay: true });
51	}
52	
53	/**
54	 * Builds serialized static-state snapshots for `load`-enabled queries across every service
55	 * currently in the registry.
56	 *
57	 * Each static input runs against a fresh service runtime so one load path cannot leak state
58	 * into another path's snapshot. The runtime's `runLoadOnce` helper drives the load to completion
59	 * (including transitively triggered self-queries) before the resulting state is captured.
60	 * Cross-service `ctx.getService(...)` lookups inside a load resolve through the live registry,
61	 * matching dev-server behavior.
62	 */
63	export async function buildStaticFiles(): Promise<StaticStore> {
64	  const store: StaticStore = {};
65	  const buildTasks: Promise<BuildTaskResult[]>[] = [];
66	
67	  for (const service of getRegisteredServices() as RuntimeServiceDefinition[]) {
68	    for (const [queryName, query] of Object.entries(service.queries) as [
69	      string,
70	      RuntimeQueryDefinition,
71	    ][]) {
72	      const { load, staticPath, staticInputs } = query;
73	      if (!staticPath || !load || !staticInputs) {
74	        continue;
75	      }
76	
77	      buildTasks.push(
78	        (async () => {
79	          const inputsRuntime = createServiceRuntime(
80	            service,
81	            { registryApi: serviceRegistryApi },
82	            structuredClone(service.initialState)
83	          );
84	          const inputs = await staticInputs(inputsRuntime.loadCtxForStatic);
85	
86	          return Promise.all(
87	            inputs.map(async (input) => {
88	              // Build every static input from a clean initial state so the serialized output mirrors
89	              // the one path this task is responsible for.
90	              const buildRuntime = createServiceRuntime(
91	                service,
92	                { registryApi: serviceRegistryApi },
93	                structuredClone(service.initialState)
94	              );
95	              const validatedInput = await validateSchema(query.input, input, {
96	                kind: 'query',
97	                serviceId: service.id,
98	                name: queryName,
99	                phase: 'input',
100	              });
101	              const path = resolveStaticPath(service.id, queryName, { staticPath }, validatedInput);
102	
103	              await buildRuntime.runLoadOnce(queryName, validatedInput);
104	
105	              return { path, state: buildRuntime.getStateSnapshot() };
106	            })
107	          );
108	        })()
109	      );
110	    }
111	  }
112	
113	  const builtStates = (await Promise.all(buildTasks)).flat();
114	
115	  for (const { path, state } of builtStates) {
116	    store[path] = path in store ? toMerged(store[path] as object, state as object) : state;
117	  }
118	
119	  return store;
120	}
121	
122	/**
123	 * Writes the registered services' static snapshots to `<outputDir>/services`.
124	 *
125	 * The snapshot keys are normalized slash-separated logical paths; splitting them here lets `join`
126	 * produce the correct native separators for the current operating system.
127	 */
128	export async function writeOpenServiceStaticFiles(outputDir: string): Promise<void> {
129	  const staticStore = await buildStaticFiles();
130	
131	  await Promise.all(
132	    Object.entries(staticStore).map(async ([relativePath, state]) => {
133	      const outputPath = join(outputDir, 'services', ...relativePath.split('/'));
134	
135	      await mkdir(dirname(outputPath), { recursive: true });
136	      await writeFile(outputPath, JSON.stringify(state, null, 2));
137	    })
138	  );
139	}
